<?php
require_once 'includes/components.php'; require_once 'config.php'; require_once 'content_repository.php';
ensureContentSchema($conn);
$posts=contentRows($conn,"SELECT slug,title,excerpt,cover_image,category,published_at,created_at FROM blog_posts WHERE status='published' ORDER BY COALESCE(published_at,created_at) DESC");
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kiến thức nha khoa | NALI Dental</title><?php renderSeo('Kiến thức nha khoa | NALI Dental','Các bài viết được biên tập và xuất bản bởi NALI Dental. Thông tin mang tính tham khảo, không thay thế thăm khám.'); ?><link rel="stylesheet" href="common.css"><link rel="stylesheet" href="theme.css">
    <link rel="stylesheet" href="dental-theme.css"><link rel="stylesheet" href="content-pages.css"></head><body><?php renderHeader('news'); ?><section class="content-hero"><h1>Kiến thức nha khoa</h1><p>Bài viết tham khảo được xuất bản từ hệ quản trị nội dung. Nội dung không thay thế tư vấn hoặc chỉ định trực tiếp của bác sĩ.</p></section><main class="content-wrap"><?php if($posts):?><div class="content-grid"><?php foreach($posts as $p):?><article class="content-card"><?php if($p['cover_image']):?><img src="<?=htmlspecialchars($p['cover_image'])?>" alt="<?=htmlspecialchars($p['title'])?>" loading="lazy" style="width:100%;height:180px;object-fit:cover;border-radius:12px;margin-bottom:14px"><?php endif;?><p class="meta"><?=htmlspecialchars($p['category']?:'Kiến thức')?> · <?=htmlspecialchars(date('d/m/Y',strtotime($p['published_at']?:$p['created_at'])))?></p><h2><?=htmlspecialchars($p['title'])?></h2><p><?=htmlspecialchars($p['excerpt']?:'Xem nội dung bài viết.')?></p><a class="content-button secondary" href="article.php?slug=<?=urlencode($p['slug'])?>">Đọc bài viết</a></article><?php endforeach;?></div><?php else:?><div class="content-empty"><h2>Chưa có bài viết được xuất bản</h2><p>Quản trị viên có thể tạo bản nháp, rà soát chuyên môn và xuất bản trong trang Quản trị nội dung.</p></div><?php endif;?></main><?php renderFooter(); ?></body></html>
